def test_get_order_by_id(api_url, auth_header, order_id, expected_status):
    """
    Test GET /store/order/{orderId} endpoint.
    """
    url = f"{api_url}/store/order/{order_id}"
    headers = auth_header
    response = requests.get(url, headers=headers)
    
    assert response.status_code == expected_status, f"Unexpected status code: {response.status_code}"
    
    if expected_status == 200:
        response_body = response.json()
        assert 'id' in response_body
        assert 'petId' in response_body
        assert 'quantity' in response_body
        assert 'shipDate' in response_body
        assert 'status' in response_body
        assert 'complete' in response_body
        assert isinstance(response_body['id'], int)
        assert isinstance(response_body['petId'], int)
        assert isinstance(response_body['quantity'], int)
        assert isinstance(response_body['shipDate'], str)
        assert isinstance(response_body['status'], str)
        assert isinstance(response_body['complete'], bool)
    elif expected_status == 400:
        assert "Invalid ID supplied" in response.text
    elif expected_status == 404:
        assert "Order not found" in response.text
    else:
        assert "Unexpected error" in response.text

